import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { OnlinePaymentPhoneComponent } from './online-payment-phone.component';

const routes: Routes = [{ path: '', component: OnlinePaymentPhoneComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class OnlinePaymentPhoneRoutingModule { }
