/* eslint-disable eqeqeq */
import { Component, OnInit } from '@angular/core';
import { SafeUrl } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { ToastController, LoadingController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { GAccount } from 'src/app/core/common/GAccount';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { OnlinePaymentModel } from 'src/app/data/model/order/CartModel';
import { CourseService } from 'src/app/data/service/course/course.service';
import { OrderService } from 'src/app/data/service/order/order.service';
import { ProductService } from '../../../../data/service/product/product.service';

@Component({
  selector: 'app-online-payment-phone',
  templateUrl: './online-payment-phone.component.html',
  styleUrls: ['./online-payment-phone.component.scss']
})
export class OnlinePaymentPhoneComponent implements OnInit {

  refId = '';
  success = 0;

  done1 = false;
  done2 = false;
  done3 = false;

  timer;

  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';

  constructor(
    private activatedRoute: ActivatedRoute,
    private orderService: OrderService,
    private router: Router,
    private courseService: CourseService,
    private productService: ProductService,
    public toastController: ToastController,
    public loadingController: LoadingController) { }

  ionViewWillEnter() {
    this.done1 = false;
    this.done2 = false;
    this.done3 = false;
  }

  ionViewWillLeave() {

    clearInterval(this.timer);
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    SharedIonic.loading(this.loadingController);

    this.activatedRoute.params.subscribe(params => {

      const p: string = params.id;

      if (p === undefined) {

        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'تراکنش با خطا مواجه شد');
        this.router.navigateByUrl(Urls.HomeUrl);
        return;

      } else {

        const id = +p.split('-')[0];
        const tId = +p.split('-')[1];

        this.activatedRoute.queryParams.subscribe(query => {

          const status: string = query.Status;
          const authority = query.Authority;

          if (
            status === undefined ||
            authority === undefined
          ) {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'تراکنش با خطا مواجه شد');
            this.router.navigateByUrl(Urls.HomeUrl);
            return;
          }

          if (
            status === '' ||
            authority === '' ||
            id <= 0
          ) {
            SharedIonic.dismissLoading(this.loadingController);
            SharedIonic.toast(this.toastController, 'تراکنش با خطا مواجه شد');
            this.router.navigateByUrl(Urls.HomeUrl);
            return;
          } else {

            this.orderService.OnlinePayment(
              new OnlinePaymentModel(id, tId, status, authority)
            ).subscribe(
              res => {
                SharedIonic.dismissLoading(this.loadingController);
                if (res.status === GResponse.SuccessStatus) {
                  SharedIonic.toast(this.toastController, 'با موفقیت انجام شد');
                  // GResponse.setCartCoursesCount(0);
                  // GResponse.CartCoursesCount = 0;
                  this.success = 1;

                  if (GAccount.IsLoggedIn()) {

                    this.forwardUrl();

                    this.courseService.GetUserCoursesId().subscribe(
                      res2 => {
                        this.done1 = true;
                        if (res2.status === GResponse.SuccessStatus) {
                          GResponse.MyCourseIds = res2.data;
                        } else {
                          GResponse.MyCourseIds = [];
                        }
                      },
                      err => {
                        this.done1 = true;
                        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
                      }
                    );

                    this.productService.GetUserProductsId().subscribe(
                      res2 => {
                        this.done2 = true;
                        if (res2.status === GResponse.SuccessStatus) {
                          GResponse.MyCourseIds = res2.data;
                        } else {
                          GResponse.MyCourseIds = [];
                        }
                      },
                      err => {
                        this.done2 = true;
                        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
                      }
                    );

                    this.orderService.GetUserCart().subscribe(
                      res2 => {
                        this.done3 = true;
                        if (res2.status === GResponse.SuccessStatus) {

                          if (res2.data.courses == null || res2.data.courses.length == 0) {
                            GResponse.setCartCoursesCount(0);
                          } else {
                            GResponse.setCartCoursesCount(res2.data.courses.length);
                          }

                          if (res2.data.products == null || res2.data.products.length == 0) {
                            GResponse.setCartProductsCount(0);
                          } else {
                            GResponse.setCartProductsCount(res2.data.products.length);
                          }
                        } else {
                          GResponse.setCartCoursesCount(0);
                          GResponse.setCartProductsCount(0);
                        }
                      },
                      err => {
                        this.done3 = true;
                        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
                      }
                    );
                  } else {
                    this.done1 = true;
                    this.done2 = true;
                    this.done3 = true;
                    this.forwardUrl();
                  }

                  this.timer = setInterval(() => {

                    if (this.done1 && this.done2 && this.done3) {

                      SharedIonic.dismissLoading(this.loadingController);
                      clearInterval(this.timer);
                    }
                  }, 1000);
                } else {
                  SharedIonic.dismissLoading(this.loadingController);
                  SharedIonic.toast(this.toastController, 'تراکنش با خطا مواجه شد');
                  this.success = 2;
                }
                this.refId = res.data;
              },
              err => {
                SharedIonic.dismissLoading(this.loadingController);
                SharedIonic.toast(this.toastController, 'تراکنش با خطا مواجه شد');
                this.router.navigateByUrl(Urls.HomeUrl);
              }
            );
          }

        });
      }
    });
  }

  forwardUrl() {
    window.location.href = 'ir.avalamooz://success';
    SharedIonic.dismissLoading(this.loadingController);
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }
}
